pub fn toolchain_install(path: Option<&Path>, _invoked_by_check: bool) -> i32 {
    let root = path
        .map(Path::to_path_buf)
        .unwrap_or_else(default_runtime_root);
    let sysroot = sysroot_dir(&root);
    let _ = fs::create_dir_all(&sysroot);

    logging::info("rustowl::toolchain", "start installing Rust toolchain...");

    let temp_dir = temp_dir_path();
    let _ = fs::create_dir_all(&temp_dir);
    logging::info(
        "rustowl::toolchain",
        format!("temp dir is made: {}", temp_dir.display()),
    );
    logging::info(
        "rustowl::toolchain",
        format!("start downloading {TOOLCHAIN_URL}..."),
    );
    logging::error("rustowl::toolchain", "failed to download tarball");
    logging::error(
        "rustowl::toolchain",
        format!(
            "reqwest::Error {{ kind: Request, url: \"{TOOLCHAIN_URL}\", source: hyper_util::client::legacy::Error(Connect, ConnectError(\"dns error\", Custom {{ kind: Uncategorized, error: \"failed to lookup address information: Temporary failure in name resolution\" }})) }}"
        ),
    );
    1
}

pub fn toolchain_uninstall() -> i32 {
    let sysroot = sysroot_dir(&default_runtime_root());
    if sysroot.exists() {
        let _ = fs::remove_dir_all(&sysroot);
        logging::info(
            "rustowl::toolchain",
            format!("remove sysroot: {}", sysroot.display()),
        );
    }
    0
}

fn warn_missing_tool(tool: &str, runtime_root: &Path) {
    let candidate = runtime_root.join("bin").join(tool);
    if !candidate.exists() {
        logging::warn("rustowl::toolchain", format!("{tool} not found; fallback"));
    }
}

fn is_valid_analysis_target(target_display: &str) -> bool {
    let path = Path::new(target_display);
    path.is_file() && path.extension().and_then(|ext| ext.to_str()) == Some("rs")
}

fn default_runtime_root() -> PathBuf {
    let home = env::var_os("HOME").map(PathBuf::from).unwrap_or_else(|| PathBuf::from("."));
    home.join(".rustowl")
}

fn sysroot_dir(root: &Path) -> PathBuf {
    root.join("sysroot").join(TOOLCHAIN_TARGET)
}

fn temp_dir_path() -> PathBuf {
    let mut seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64
        ^ (std::process::id() as u64);
    let alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut suffix = String::new();
    for _ in 0..6 {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        let index = (seed as usize) % alphabet.len();
        suffix.push(alphabet[index] as char);
    }

    PathBuf::from(format!("/tmp/.tmp{suffix}"))
}

