132	        seed ^= seed >> 7;
133	        seed ^= seed << 17;
134	        let index = (seed as usize) % alphabet.len();
135	        suffix.push(alphabet[index] as char);
136	    }
137	
138	    PathBuf::from(format!("/tmp/.tmp{suffix}"))
139	}
