 14	pub fn run_stdio_server() -> i32 {
 15	    help::print_banner();
 16	
 17	    let stdin = io::stdin();
 18	    let mut reader = BufReader::new(stdin.lock());
 19	    let stdout = io::stdout();
 20	    let mut writer = stdout.lock();
 21	
 22	    let mut initialized = false;
 23	
 24	    loop {
 25	        let Some(body) = read_message(&mut reader) else {
 26	            return 0;
 27	        };
 28	
 29	        let parsed = parse_json(&body);
 30	        let response = match parsed {
 31	            Ok(JsonValue::Object(fields)) => handle_message(&fields, &mut initialized),
 32	            Ok(_) => Some(error_response(None, -32600, "Invalid request", None)),
 33	            Err(_) => Some(error_response(None, -32700, "Parse error", None)),
 34	        };
 35	
 36	        if let Some(response) = response {
 37	            if write_message(&mut writer, &response).is_err() {
 38	                return 1;
 39	            }
 40	        }
 41	    }
 42	}
