 44	fn handle_message(fields: &[(String, JsonValue)], initialized: &mut bool) -> Option<String> {
 45	    let id = fields.iter().find(|(key, _)| key == "id").map(|(_, value)| value);
 46	    let method = fields
 47	        .iter()
 48	        .find(|(key, _)| key == "method")
 49	        .and_then(|(_, value)| match value {
 50	            JsonValue::String(text) => Some(text.as_str()),
 51	            _ => None,
 52	        });
 53	    let params = fields.iter().find(|(key, _)| key == "params").map(|(_, value)| value);
 54	
 55	    let Some(method) = method else {
 56	        return Some(error_response(id, -32600, "Invalid request", None));
 57	    };
 58	
 59	    if !*initialized {
 60	        if method == "initialize" {
 61	            if *initialized {
 62	                return Some(error_response(id, -32600, "Invalid request", None));
 63	            }
 64	            *initialized = true;
 65	            return Some(initialize_response(id));
 66	        }
 67	        return Some(error_response(id, -32002, "Server not initialized", None));
 68	    }
 69	
 70	    match method {
 71	        "initialize" => Some(error_response(id, -32600, "Invalid request", None)),
 72	        "shutdown" => {
 73	            if let Some(params) = params {
 74	                Some(error_response(
 75	                    id,
 76	                    -32602,
 77	                    &format!("Unexpected params: {}", params.to_compact()),
 78	                    None,
 79	                ))
 80	            } else {
 81	                Some(result_response(id, "null"))
 82	            }
 83	        }
 84	        "exit" => None,
 85	        "initialized"
 86	        | "textDocument/didOpen"
 87	        | "textDocument/didChange"
 88	        | "textDocument/didSave"
 89	        | "textDocument/didClose"
 90	        | "workspace/didChangeWorkspaceFolders" => None,
 91	        _ => {
 92	            if id.is_some() {
 93	                Some(error_response(
 94	                    id,
 95	                    -32601,
 96	                    "Method not found",
 97	                    Some(method),
 98	                ))
 99	            } else {
100	                None
101	            }
102	        }
103	    }
104	}
