136	fn read_message<R: BufRead>(reader: &mut R) -> Option<String> {
137	    let mut content_length: Option<usize> = None;
138	
139	    loop {
140	        let mut line = String::new();
141	        let bytes = reader.read_line(&mut line).ok()?;
142	        if bytes == 0 {
143	            return None;
144	        }
145	        if line == "\r\n" || line == "\n" {
146	            break;
147	        }
148	
149	        let lower = line.to_ascii_lowercase();
150	        if lower.starts_with("content-length:") {
151	            let value = line.split_once(':')?.1.trim();
152	            content_length = value.parse::<usize>().ok();
153	        }
154	    }
155	
156	    let length = content_length?;
157	    let mut buffer = vec![0u8; length];
158	    reader.read_exact(&mut buffer).ok()?;
159	    Some(String::from_utf8_lossy(&buffer).to_string())
160	}
