167	fn parse_json(input: &str) -> Result<JsonValue, String> {
168	    let mut parser = Parser::new(input);
169	    let value = parser.parse_value()?;
170	    parser.skip_ws();
171	    if parser.is_eof() {
172	        Ok(value)
173	    } else {
174	        Err("trailing characters".to_string())
175	    }
