178	fn json_string(value: &str) -> String {
179	    let mut out = String::with_capacity(value.len() + 2);
180	    out.push('"');
181	    for ch in value.chars() {
182	        match ch {
183	            '"' => out.push_str("\\\""),
184	            '\\' => out.push_str("\\\\"),
185	            '\n' => out.push_str("\\n"),
186	            '\r' => out.push_str("\\r"),
187	            '\t' => out.push_str("\\t"),
188	            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
189	            c => out.push(c),
190	        }
191	    }
192	    out.push('"');
193	    out
194	}
