196	impl JsonValue {
197	    fn to_compact(&self) -> String {
198	        match self {
199	            JsonValue::Null => "null".to_string(),
200	            JsonValue::Bool(value) => value.to_string(),
201	            JsonValue::Number(value) => value.clone(),
202	            JsonValue::String(value) => json_string(value),
203	            JsonValue::Array(items) => {
204	                let parts: Vec<String> = items.iter().map(JsonValue::to_compact).collect();
205	                format!("[{}]", parts.join(","))
206	            }
207	            JsonValue::Object(fields) => {
208	                let parts: Vec<String> = fields
209	                    .iter()
210	                    .map(|(key, value)| format!("{}:{}", json_string(key), value.to_compact()))
211	                    .collect();
212	                format!("{{{}}}", parts.join(","))
213	            }
214	        }
215	    }
216	}
